// Родные названия языков (для выбора языка) и языки с письмом справа-налево.
export const LANG_NAMES = {
  ru: 'Русский', en: 'English', it: 'Italiano', id: 'Bahasa Indonesia', es: 'Español', ar: 'العربية', fr: 'Français',
};
const RTL_LANGS = ['ar'];
export function isRTL(lang = _lang) { return RTL_LANGS.includes(lang); }
export function dir(lang = _lang) { return isRTL(lang) ? 'rtl' : 'ltr'; }

let _lang = 'ru';

export function setLang(lang) {
  if (DICT[lang]) _lang = lang;
}

export function getLang() {
  return _lang;
}

export function availableLangs() {
  return Object.keys(DICT);
}

export function t(key, vars) {
  const str = (DICT[_lang] && DICT[_lang][key]) || (DICT.ru[key]) || key;
  if (!vars) return str;
  return str.replace(/\{(\w+)\}/g, (_, k) => (vars[k] != null ? vars[k] : `{${k}}`));
}
